// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 blockTime) public {
        vm.assume(blockTime > 0);
        vm.warp(blockTime);
        vm.roll(1);

        address actor1 = makeAddr("actor1");
        address actor2 = makeAddr("actor2");
        vm.deal(actor1, 20 ether);
        vm.deal(actor2, 20 ether);

        vm.prank(actor1);
        (bool ok1,) = address(c).call{value: 10 ether}("");
        require(ok1, "first call must succeed");
        uint256 afterFirst = c.pastBlockTime();

        vm.prank(actor2);
        (bool ok2,) = address(c).call{value: 10 ether}("");
        if (ok2) {
            uint256 afterSecond = c.pastBlockTime();
            assertTrue(afterSecond > afterFirst);
        }
    }
}
